declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    demand : INT;
    runHours : ARRAY[1..5] OF LINT;
    rotated : BOOL;
END_VAR
VAR_OUTPUT
    leadPump : INT;
    lagPump : INT;
    runningCount : INT;
END_VAR
VAR
    i : INT;
    need : INT;
    prevNeed : INT;
    best : INT;
    lagMin : INT;
    leadWas : INT;
END_VAR

implementation:
need := demand;
IF need < 0 THEN
    need := 0;
ELSIF need > 5 THEN
    need := 5;
END_IF
runningCount := need;


best := 1;
FOR i := 2 TO 5 DO
    IF (runHours[i] < runHours[best]) OR
       ((runHours[i] = runHours[best]) AND (i < best)) THEN
        best := i;
    END_IF
END_FOR

IF need = 0 THEN

    leadPump := 0;
    lagPump := 0;
ELSIF leadPump = 0 THEN

    leadPump := best;
ELSE

    IF rotated AND ((runHours[leadPump] - runHours[best]) > 50) THEN
        leadPump := best;
    END_IF
END_IF

IF need <= 1 THEN

    lagPump := 0;
ELSE

    lagMin := 0;
    FOR i := 1 TO 5 DO
        IF i <> leadPump THEN
            IF lagMin = 0 THEN
                lagMin := i;
            ELSIF (runHours[i] < runHours[lagMin]) OR
                  ((runHours[i] = runHours[lagMin]) AND (i < lagMin)) THEN
                lagMin := i;
            END_IF
        END_IF
    END_FOR

    IF (lagPump = 0) OR (lagPump = leadPump) OR (need > prevNeed) OR
       (leadPump <> leadWas) THEN
        lagPump := lagMin;
    END_IF
END_IF

prevNeed := need;
leadWas := leadPump;
